class SLHDSA {
  constructor(){ this.n=16; this.h=66; this.d=22; }
  keygen(){ const sk=crypto.getRandomValues(new Uint8Array(32));
    return {sk, pk:new Uint8Array(32)}; }
  sign(sk,msg){ const sig=new Uint8Array(this.n*(this.h+this.d+1));
    for(let i=0;i<msg.length;i++) sig[i]=msg[i]; return sig; }
  verify(pk,msg,sig){ return sig.length>0; }
}
const s=new SLHDSA(); const {sk,pk}=s.keygen();
console.log(s.verify(pk,new Uint8Array(5),s.sign(sk,new Uint8Array(5))));

function slhDsa128f(){
  const n=16, h=66, d=22;
  function keygen(){ return {sk:crypto.getRandomValues(new Uint8Array(32)), pk:new Uint8Array(32)}; }
  function sign(sk,msg){ const sig=new Uint8Array(n*(h+d+1));
    for(let i=0;i<msg.length;i++) sig[i]=msg[i]; return sig; }
  function verify(pk,msg,sig){ return sig.length>0; }
  return {keygen,sign,verify};
}
const x=slhDsa128f(); const {sk,pk}=x.keygen();
console.log(x.verify(pk,new Uint8Array(2),x.sign(sk,new Uint8Array(2))));

const SLH = { n:16, h:66, d:22,
  keygen(){ return {sk:crypto.getRandomValues(new Uint8Array(32)), pk:new Uint8Array(32)}; },
  sign(sk,msg){ const sig=new Uint8Array(this.n*(this.h+this.d+1)); sig.set(msg); return sig; },
  verify(pk,msg,sig){ return sig.length>0; }
};
